final case class Order private (
    id: OrderId, lines: Vector[OrderLine], total: Long, limit: Long) {
  def addLine(l: OrderLine): Either[DomainError, Order] =
    if total + l.amount > limit then Left(DomainError.CreditLimit)
    else Right(copy(lines = lines :+ l, total = total + l.amount))
}
object Order:
  def apply(id: OrderId, limit: Long): Either[DomainError, Order] =
    Right(new Order(id, Vector.empty, 0L, limit))

